mapper.select:
SELECT a.id, a.title, a.subtitle, a.link, a.today_challenge, a.published_at, a.created_at FROM news_articles a LEFT JOIN news_activities na ON na.article_id = a.id AND na.child_id = #{childId}
AND na.completed_at IS NOT NULL
AND na.completed_at IS NULL
ORDER BY a.published_at DESC, a.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM news_articles a LEFT JOIN news_activities na ON na.article_id = a.id AND na.child_id = #{childId}
AND na.completed_at IS NOT NULL
AND na.completed_at IS NULL

SELECT id, title, subtitle, link, today_challenge, published_at, created_at
FROM news_articles
WHERE id = #{id}

SELECT EXISTS(
    SELECT 1 FROM news_articles WHERE link = #{link}
)

SELECT EXISTS(
    SELECT 1
    FROM users
    WHERE id = #{childId}
      AND user_type = 'CHILD'
)

SELECT EXISTS(
    SELECT 1
    FROM family_relations
    WHERE parent_id = #{parentId}
      AND child_id = #{childId}
      AND status = 'ACTIVE'
)
